  `cus_demand` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '客户需求',
  `cus_moment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户说说',
  `intention_max_age` int NULL DEFAULT NULL COMMENT '择偶最大年龄',
  `intention_min_age` int NULL DEFAULT NULL COMMENT '择偶最小年龄',
  `intention_have_house_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '择偶房产要求编码',
