  `wal_total_earned` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '累计收益',
  `wal_total_withdrawn` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '累计提现',
  PRIMARY KEY (`id`) USING BTREE,
